'use strict';
Object.assign(PRIORITIES,{q1:'Quan trọng, khẩn cấp',q2:'Quan trọng, không khẩn cấp',q3:'Không quan trọng, khẩn cấp',q4:'Không quan trọng, không khẩn cấp'});
function matrixChip(t){return t.priority?`<span class="matrix-chip ${t.priority}" title="${esc({q1:'Quan trọng, khẩn cấp',q2:'Quan trọng, không khẩn cấp',q3:'Không quan trọng, khẩn cấp',q4:'Không quan trọng, không khẩn cấp'}[t.priority])}">${esc(PRIORITIES[t.priority])}</span>`:'';}
function taskPreferences(){return {progress:localRead('kanban-progress')!=='off',checks:localRead('kanban-checks')==='on'};}
// Use the original compact card without its external next-step button.
taskCard=function(t,p){const pref=taskPreferences(),pct=taskPct(t);return `<article class="task-card" draggable="true" data-task="${esc(t.id)}" data-pid="${esc(p.id)}" role="button" tabindex="0"><span class="tag">${esc(t.tag||'Công việc')}</span>${matrixChip(t)}${labelChips(t)}<h3>${esc(t.title)}</h3>${t.description?'<p>'+esc(t.description.slice(0,100))+'</p>':''}${pref.progress?'<div class="progress-meta"><span>'+t.checks.filter(c=>c.done).length+'/'+t.checks.length+' mục</span><strong>'+pct+'%</strong></div>'+bar(pct,p.color):''}${pref.checks?'<ul class="card-checks">'+t.checks.slice(0,5).map(c=>'<li class="'+(c.done?'completed':'')+'"><span class="card-check-mark" aria-hidden="true">'+(c.done?'✓':'')+'</span><span>'+esc(c.text)+'</span></li>').join('')+(t.checks.length>5?'<li class="card-check-more">+'+(t.checks.length-5)+' mục khác · Mở task để xem</li>':'')+'</ul>':''}<div class="task-footer">${t.due?'Hạn '+dateLabel(t.due):'Chưa đặt hạn'}${t.due&&t.due<today()&&t.col!=='Done'?' · Quá hạn':''}</div></article>`;};
const baseBoardUX=board;board=function(){const pref=taskPreferences();return '<div class="kanban-options"><label><input type="checkbox" data-kanban-option="progress" '+(pref.progress?'checked':'')+'> Thanh tiến độ</label><label><input type="checkbox" data-kanban-option="checks" '+(pref.checks?'checked':'')+'> Hiện checklist trên thẻ</label></div>'+baseBoardUX();};
const baseDashboardUX=dashboard;dashboard=function(){const overdue=allTasks().filter(t=>t.col!=='Done'&&(t.end?.slice(0,10)||t.due)&& (t.end?.slice(0,10)||t.due)<today()).length;return baseDashboardUX().replace('<p class="chart-foot">','<div class="overdue-total">Quá hạn <strong>'+overdue+'</strong><small>Công việc chưa hoàn tất, đã qua ngày kết thúc</small></div><p class="chart-foot">');};
const baseTimelineTaskUX=timelineTask;timelineTask=function(t){return baseTimelineTaskUX(t).replace('</button>',matrixChip(t)+bar(taskPct(t),t.project.color)+'</button>');};
const baseCalendarUX=workCalendar;workCalendar=function(){return baseCalendarUX().replace(/(<button class="month-event[\s\S]*?data-task="([^"]+)"[\s\S]*?data-pid="([^"]+)"[\s\S]*?)(<\/button>)/g,(whole,body,id,pid,end)=>{const p=project(pid),t=p?.tasks.find(t=>t.id===id);return t?body+matrixChip(t)+'<span class="calendar-progress">'+taskPct(t)+'%</span>'+bar(taskPct(t),p.color)+end:whole;});};
taskDetail=function(p,t){taskForm(p,t);const body=$('#editor-body'),form=$('#editor-form'),next=p.columns[p.columns.indexOf(t.col)+1];body.insertAdjacentHTML('afterbegin','<p class="eyebrow">'+esc(p.name)+' · Chi tiết công việc</p><div class="detail-actions"><button class="btn" type="button" data-files="'+esc(p.id)+'" data-file-task="'+esc(t.id)+'">'+svgIcon('attach')+'Tệp đính kèm</button>'+(next?'<button class="btn" type="button" id="detail-next">Chuyển sang '+esc(next)+' →</button>':'')+'<button type="button" class="btn danger" data-action="delete-task">Xóa</button></div>'+matrixChip(t));body.insertAdjacentHTML('beforeend','<h3>Checklist</h3>'+t.checks.map((c,i)=>`<div class="inline-check compact-check ${c.done?'is-complete':''}"><input type="checkbox" name="check-done-${i}" aria-label="Hoàn thành mục ${i+1}" ${c.done?'checked':''}><textarea name="check-text-${i}" aria-label="Nội dung mục ${i+1}" maxlength="300" required rows="1">${esc(c.text)}</textarea><input type="checkbox" name="check-remove-${i}" hidden><button type="button" class="compact-check-remove" data-compact-remove="${i}" aria-label="Bỏ mục ${i+1}" title="Bỏ mục">×</button></div>`).join('')+'<label class="field">Thêm checklist (mỗi dòng một mục)<textarea name="extra-checks" maxlength="20000"></textarea></label><p class="help-copy">Chỉnh trực tiếp các trường, rồi chọn Lưu thay đổi. Chuyển sang cột tiếp theo cũng lưu nội dung đang chỉnh.</p>');const submit=form.onsubmit;const wrapper=e=>{e.preventDefault();const fd=new FormData(form),original=structuredClone(t.checks),updated=[];for(let i=0;i<t.checks.length;i++){const c=t.checks[i];if(fd.has('check-remove-'+i))continue;const start=c.start||'',end=c.end||'';if(start&&end&&start>end)return notify('Kết thúc checklist phải sau bắt đầu.');const text=String(fd.get('check-text-'+i)||'').trim();if(!text)return notify('Nội dung checklist không được để trống.');updated.push({...c,text,done:fd.has('check-done-'+i),start,end});}const extra=String(fd.get('extra-checks')||'').split('\n').map(s=>s.trim()).filter(Boolean);if(updated.length+extra.length>200)return notify('Tối đa 200 mục checklist.');const before=structuredClone(data);t.checks=[...updated,...extra.map(text=>({id:uid(),text:text.slice(0,300),done:false}))];moveToTrash(before);if(!fd.get('title').trim()||!validDate(fd.get('due'))||(fd.get('start')&&fd.get('end')&&fd.get('start')>fd.get('end'))){t.checks=original;data.trash=before.trash;return notify('Kiểm tra tên và khoảng thời gian công việc.');}if(form.elements.col.value===t.col&&updated.length&&!extra.length&&!original.every(c=>c.done)&&updated.every(c=>c.done))form.elements.col.value='Done';else if(t.col==='Done'&&form.elements.col.value==='Done'&&updated.some(c=>!c.done))form.elements.col.value=p.columns.includes('Doing')?'Doing':p.columns[0];submit(e);if(form.onsubmit===wrapper){t.checks=original;data.trash=before.trash;} };form.onsubmit=wrapper;if(next)$('#detail-next').onclick=()=>{form.elements.col.value=next;form.requestSubmit();};};
// taskForm calls taskDetail only after saving, so the editor remains a single screen.
document.addEventListener('change',e=>{const key=e.target.dataset.kanbanOption;if(key){localWrite('kanban-'+key,e.target.checked?'on':'off');render();}});
help=function(){const sections=[['natureProjects','Bắt đầu từ toàn cảnh','Dashboard cho biết số dự án đang chạy và bốn nhóm công việc: hoàn thành, đang xây dựng, chưa làm, quá hạn. Chạm hoặc rê chuột lên biểu đồ để xem danh sách. Việc quá hạn được tách riêng, không đếm trùng.'],['leaf','Sắp xếp dự án','Mỗi tab là một dự án. Kéo để đổi vị trí; ghim để thu nhỏ và vẫn xem được tiến độ. Tìm theo tên hoặc từ khóa có màu. Lưu trữ giữ nguyên trạng thái để khôi phục khi cần.'],['check','Làm từng bước','Mở công việc để sửa tên, mô tả, trạng thái, lịch và Mức độ. Checklist chia việc thành các bước nhỏ. Chọn Lưu thay đổi để áp dụng; chuyển sang cột kế tiếp cũng lưu nội dung đang sửa. Done đánh dấu các mục hoàn tất.'],['calendar','Chọn cách nhìn phù hợp','Kanban giúp sắp xếp theo trạng thái; Timeline theo mốc thời gian; Calendar theo tháng. Gantt thể hiện thứ tự hỗ trợ giữa các việc: nối hai chấm để tạo quan hệ hoàn thành → bắt đầu. Liên kết không tự dời lịch.'],['natureFocus','Chọn mức độ ưu tiên','Tím: quan trọng, khẩn cấp. Xanh lá: quan trọng, không khẩn cấp. Hồng: không quan trọng, khẩn cấp. Cam: không quan trọng, không khẩn cấp. Bấm trực tiếp nhãn màu trong form để chọn.'],['notes','Ghi lại ý tưởng và tài liệu','Bấm card để mở ghi chú; viết nội dung, thêm liên kết hoặc tải tệp ngay trong khung. Tài nguyên tập hợp tệp theo album, có xem chi tiết, đổi tên và chuyển vào Thùng rác. Tối đa 25 MB/tệp, tổng kho 1 GB tính cả Thùng rác.'],['cloudCheck','Đồng bộ và nhắc việc','Xanh lá báo đã đồng bộ; vàng báo đang chờ hoặc cần chú ý. Thay đổi ngoại tuyến được giữ trên thiết bị. Chuông mở chi tiết công việc, tệp mới và phiên bản. Settings cho phép chọn giờ nhắc hạn hằng ngày, tổng kết Chủ nhật và xem trước/In/Lưu PDF.'],['settings','Giữ dữ liệu và phiên làm việc','Xuất JSON định kỳ. Khi có xung đột, giữ bản sao trước khi chọn dữ liệu máy chủ. Dữ liệu trong Thùng rác có thể khôi phục trong 30 ngày. Tải lại trang vẫn giữ phiên; sau 10 phút không thao tác cần đăng nhập lại. Đăng xuất có xác nhận tại cuối Settings.']];modal('<div class="guide-intro"><span class="guide-mark">'+svgIcon('leaf')+'</span><h2>Nhìn rõ việc, giữ nhịp an nhiên</h2><p>Một không gian để ghi lại, chọn ưu tiên và tiến từng bước. Tiến độ giúp bạn điều chỉnh nhịp làm việc.</p></div><div class="guide-grid">'+sections.map(([icon,title,text])=>'<section class="guide-card"><h3>'+svgIcon(icon)+title+'</h3><p>'+text+'</p></section>').join('')+'</div>',null,true);};
document.addEventListener('click',e=>{if(!e.target.closest('[data-files]')||!$('#editor-body .inline-check')&&!$('#editor-body #detail-next'))return;const f=$('#editor-form'),prior=f.onsubmit;f.requestSubmit();if(f.onsubmit===prior){e.preventDefault();e.stopImmediatePropagation();}},true);
